/**
 * Compute expanded AABB covering capsule movement from start to end position.
 * Used for broad-phase culling of BVH nodes.
 *
 * @param {Object} capsuleInfo - Capsule geometry info (radius, segment)
 * @param {THREE.Matrix4} matrix - Current capsule world matrix
 * @param {THREE.Vector3} velocity - Total local velocity
 * @param {number} delta - Timestep in seconds
 * @returns {THREE.Box3} Expanded AABB covering the sweep
 */
export function computeSweepAABB(capsuleInfo: any, matrix: THREE.Matrix4, velocity: THREE.Vector3, delta: number): THREE.Box3;
/**
 * Binary search to find first collision time along movement path.
 *
 * @param {Object} body - Physics body
 * @param {THREE.Vector3} displacement - Full movement vector (velocity * delta)
 * @param {number} [maxIterations=6] - Max binary search iterations
 * @returns {number} Time of first collision (0.0 to 1.0), or 1.0 if no collision
 */
export function findFirstCollisionTime(body: any, displacement: THREE.Vector3, maxIterations?: number): number;
/**
 * Save the body position before integration.
 * Must be called BEFORE dynamic() to enable sweep correction.
 *
 * @param {Object} body - Physics body
 */
export function savePreIntegrationPosition(body: any): void;
/**
 * Sweep movement path to find safe position.
 * Uses binary search to detect first collision along movement vector.
 * Prevents tunneling through thin geometry at high velocities.
 *
 * IMPORTANT: Call savePreIntegrationPosition() BEFORE dynamic(),
 * then call this function AFTER dynamic() to apply correction.
 *
 * This function also captures and sets surface collision data (surfaceAngle, surfaceNormal)
 * since CCD positions the body BEFORE penetration, preventing trimeshCollide from detecting it.
 *
 * @param {Object} body - Physics body
 * @param {BufferBackedObject} sDynamic - Shared buffer view
 * @param {number} delta - Timestep in seconds
 * @param {number} index - Body index
 * @returns {number} Safe movement fraction (0.0 to 1.0)
 */
export function sweepMovement(body: any, sDynamic: BufferBackedObject, delta: number, index: number): number;
